Resource: aws_api_gateway_rest_api.this
File: /api.tf: 1-8
Guideline: https://docs.prismacloud.io/en/enterprise-edition/policy-reference/aws-policies/aws-general-policies/ensure-aws-api-gateway-enables-create-before-destroy

		1 | resource "aws_api_gateway_rest_api" "this" {
		2 |   name        = "${local.name}-api"
		3 |   description = "API REST del MVP TuCochera"
		4 | 
		5 |   endpoint_configuration {
		6 |     types = ["REGIONAL"]
		7 |   }
		8 | }

Resource: aws_iam_policy_document.kms
File: /security.tf: 51-95
Guideline: https://docs.prismacloud.io/en/enterprise-edition/policy-reference/aws-policies/aws-iam-policies/ensure-iam-policies-do-not-allow-write-access-without-constraint

		51 | data "aws_iam_policy_document" "kms" {
		52 |   statement {
		53 |     sid       = "AdminCuenta"
		54 |     actions   = ["kms:*"]
		55 |     resources = ["*"]
		56 | 
		57 |     principals {
		58 |       type        = "AWS"
		59 |       identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
		60 |     }
		61 |   }
		62 | 
		63 |   statement {
		64 |     sid       = "LecturaCloudFront"
		65 |     actions   = ["kms:Decrypt", "kms:GenerateDataKey*"]
		66 |     resources = ["*"]
		67 | 
		68 |     principals {
		69 |       type        = "Service"
		70 |       identifiers = ["cloudfront.amazonaws.com"]
		71 |     }
		72 | 
		73 |     condition {
		74 |       test     = "StringEquals"
		75 |       variable = "AWS:SourceArn"
		76 |       values   = ["arn:aws:cloudfront::${data.aws_caller_identity.current.account_id}:distribution/*"]
		77 |     }
		78 |   }
		79 |   statement {
		80 |     sid       = "LogsCloudWatch"
		81 |     actions   = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:Describe*"]
		82 |     resources = ["*"]
		83 | 
		84 |     principals {
		85 |       type        = "Service"
		86 |       identifiers = ["logs.${var.aws_region}.amazonaws.com"]
		87 |     }
		88 | 
		89 |     condition {
		90 |       test     = "ArnLike"
		91 |       variable = "kms:EncryptionContext:aws:logs:arn"
		92 |       values   = ["arn:aws:logs:${var.aws_region}:${data.aws_caller_identity.current.account_id}:*"]
		93 |     }
		94 |   }
		95 | }

